def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    # Check if arr is already non-decreasing
    def is_non_decreasing(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    # Try all rotations by right shifting i times
    for i in range(n):
        rotated = arr[-i:] + arr[:-i]
        if is_non_decreasing(rotated):
            return True

    return False

