from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses as an integer. 

    The function should not use any loops or recursion to solve this task.

    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    def max_depth(s: str, current: int = 0, max_d: int = 0) -> int:
        # This helper uses no explicit loops or recursion in parse_nested_parens itself.
        # But since recursion is forbidden in parse_nested_parens itself, we won't
        # use this helper recursively. So we must implement depth calculation without loops or recursion.
        # Instead we implement depth calculation using str methods and max on a generated list.

        # Since we can't use loops or recursion, we'll use a functional approach with map and helper functions.

        # However, map is a built-in function, allowed as it's part of standard library.

        # We'll create a list of prefix sums of +1 for '(' and -1 for ')'.

        # To do this without loops or recursion, use itertools.accumulate.

        import itertools

        vals = list(map(lambda c: 1 if c == '(' else -1 if c == ')' else 0, s))
        prefix_sums = list(itertools.accumulate(vals))
        return max(prefix_sums) if prefix_sums else 0

    # Now parse_nested_parens itself must not contain loops or recursion.
    # We'll split the input by spaces (str.split())
    groups = paren_string.split()

    # Use map to apply max_depth to each group and return list of results
    return list(map(max_depth, groups))

