def monotonic(l):
    if isinstance(l, str):
        # For strings: Return True if strictly monotonic increasing or decreasing without duplicates, else False.
        # Also return the string itself if True.
        # Check duplicates:
        if any(l.count(c) > 1 for c in l):
            return False
        # Check strictly increasing:
        inc = all(l[i] < l[i+1] for i in range(len(l)-1))
        # Check strictly decreasing:
        dec = all(l[i] > l[i+1] for i in range(len(l)-1))
        if inc or dec:
            return True, l
        else:
            return False
    else:
        # For lists: Return True if non-decreasing or non-increasing (allow duplicates), else False.
        # sum elements as int if True.
        if not l:
            # Empty list is monotonic, sum is 0
            return True
        non_decreasing = all(l[i] <= l[i+1] for i in range(len(l)-1))
        non_increasing = all(l[i] >= l[i+1] for i in range(len(l)-1))
        if non_decreasing or non_increasing:
            return True
        else:
            return False

