def search(lst):
    from collections import Counter

    counts = Counter(lst)
    if not lst:
        return -1

    # Check if the list contains strings (any element is a str)
    if any(isinstance(x, str) for x in lst):
        # For string input, return lex greatest string
        # Among all strings in lst, return the lex greatest string
        strings = list(filter(lambda x: isinstance(x, str), counts))
        if not strings:
            return -1
        return max(strings)
    else:
        # For numeric input, find greatest integer > 0 whose frequency >= integer itself
        # collect candidates without using loops
        candidates = list(filter(lambda x: isinstance(x, int) and x > 0 and counts[x] >= x, counts))
        if not candidates:
            return -1
        return max(candidates)

