    def total_digits(lst):
        count = 0
        for x in lst:
            s = str(x)
            for ch in s:
                if ch.isdigit():
                    count += 1
        return count

    count1 = total_digits(lst1)
    count2 = total_digits(lst2)

    if count1 <= count2:
        return lst1
    else:
        return lst2

