def prime_length(string):
    """Write a function that takes a string and returns 1 if the string
    length is a prime number or 0 otherwise.
    """
    n = len(string)
    if n < 2:
        return 0
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return 0
    return 1

