def anti_shuffle(s):
    import re
    parts = re.split(r'(\s+)', s)
    result_parts = []
    for part in parts:
        if part.isspace() or part == '':
            result_parts.append(part)
        else:
            # sort characters of the word descending by ascii value
            sorted_word = ''.join(sorted(part, reverse=True))
            result_parts.append(sorted_word)
    return ''.join(result_parts)

