def move_one_ball(arr):
    if not arr:
        return True
    sorted_arr = sorted(arr)
    n = len(arr)
    # Find the index in arr where sorted_arr[0] is located
    try:
        start = arr.index(sorted_arr[0])
    except ValueError:
        return False
    # Generate the rotated version of arr starting at index start
    rotated = arr[start:] + arr[:start]
    # Check if rotated matches sorted_arr
    return rotated == sorted_arr

