def maximum(arr, k):
    """
    Given an array arr of integers or strings and a non-negative integer k (0 <= k <= len(arr)), 
    return a sorted list of length k with the maximum k numbers in arr. The list should be sorted 
    in ascending order. The output list must be sorted in ascending order regardless of the elements’ 
    original relative positions.

    Constraints:
        - No built-in sorting functions are allowed.
        - The function should work for strings as well.
    """
    # Handle edge case
    if k == 0:
        return []

    # Find the k largest elements without built-in sorting
    # Using a simple selection approach k times to find largest elements
    arr_copy = list(arr)  # copy to avoid modifying original
    largest_elements = []
    for _ in range(k):
        max_elem = arr_copy[0]
        for elem in arr_copy[1:]:
            if elem > max_elem:
                max_elem = elem
        largest_elements.append(max_elem)
        arr_copy.remove(max_elem)

    # Now, sort largest_elements in ascending order without built-in sort
    # Use a simple insertion sort (since k <= len(arr) <= 1000, this is acceptable)
    for i in range(1, k):
        key = largest_elements[i]
        j = i - 1
        while j >= 0 and largest_elements[j] > key:
            largest_elements[j + 1] = largest_elements[j]
            j -= 1
        largest_elements[j + 1] = key

    return largest_elements

