def sum_squares(lst):
    def ceil_num(x):
        # If x is already an integer, return x as int
        if int(x) == x:
            return int(x)
        # If x is positive and not an integer, return int part + 1
        if x > 0:
            return int(x) + 1
        # If x is negative and not an integer, return int part (which is ceiling for negatives)
        return int(x)

    def helper(index):
        if index == len(lst):
            return 0
        c = ceil_num(lst[index])
        return c * c + helper(index + 1)

    return helper(0)

