def sort_even(items):
    def sort_even(items):
        even_indices = [i for i in range(len(items)) if i % 2 == 0]
        even_elements = [items[i] for i in even_indices]
        even_elements.sort()
        result = list(items)
        for idx, val in zip(even_indices, even_elements):
            result[idx] = val
        return result
    return sort_even(items)

