def sum_squares(lst):
    """
    This function takes a list of integers and returns the sum of all entries after processing:
    - entries at indexes that are multiples of 3 are squared,
    - entries at indexes that are multiples of 4 but not 3 are cubed,
    - all other entries remain unchanged.
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total

