def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a sorted list 
    of length k with the maximum k numbers in arr.

    The output list contains exactly k elements when k > 0, counting duplicates 
    separately, sorted in ascending order. If k == 0, return an empty list.
    """
    if k == 0:
        return []
    sorted_arr = sorted(arr, reverse=True)
    top_k = sorted_arr[:k]
    return sorted(top_k)

