def select_words(s, n):
    """Given a string s and a natural number n, return a list of all words from s
    that contain at least one letter repeated exactly n times.
    """
    words = s.split()
    result = []
    for word in words:
        counts = {}
        for ch in word:
            counts[ch] = counts.get(ch, 0) + 1
        if any(count == n for count in counts.values()):
            result.append(word)
    return result

