def prime_length(string):
    """Write a function that takes a string and returns True if the string
    length is a prime number greater than 1 or False otherwise.
    """
    n = len(string)
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

