def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Count the number of "drops" where arr[i] > arr[i+1] in circular manner
    drops = 0
    for i in range(n):
        if arr[i] > arr[(i+1) % n]:
            drops += 1
            if drops > 1:
                return False
    return True

