def sum_squares(lst):
    """
    This function takes a list of integers and transforms each entry based on its index:
    - If the index is a multiple of 3, square the entry.
    - Else if the index is a multiple of 4 and not a multiple of 3, cube the entry.
    - Otherwise, keep the entry unchanged.
    Then, it returns the sum of all transformed entries.
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0 and i % 3 != 0:
            total += val ** 3
        else:
            total += val
    return total

