def parse_nested_parens(paren_string):
    """ Input to this function is a string. Output a list of deepest nesting levels 
        corresponding to each group of parentheses separated by spaces in the input string.
    """
    groups = paren_string.split()
    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
