def smallest_change(arr):
    """
    Find the minimum number of elements that need to be changed to make the array palindromic.

    Args:
        arr: list of elements

    Returns:
        int: minimum number of elements to change
    """
    n = len(arr)
    count = 0
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            count += 1
    return count

