def digits(n):
    """Given an integer n, return the product of the odd digits.

    If no odd digits are present, return 0.
    """
    product = 1
    found_odd = False
    for ch in str(abs(n)):
        digit = int(ch)
        if digit % 2 == 1:
            product *= digit
            found_odd = True
    return product if found_odd else 0

