def parse_music(music: str) -> list[int]:
    token_map = {
        "o": 1,
        "o|": 2,
        ".|": 3
    }
    result = []
    i = 0
    while i < len(music):
        # Try to match two-character tokens first
        if i + 1 < len(music):
            two_char = music[i:i+2]
            if two_char in token_map:
                result.append(token_map[two_char])
                i += 2
                continue
        # Then single-character tokens
        if music[i] in token_map:
            result.append(token_map[music[i]])
            i += 1
            continue
        # Skip characters that are not tokens
        i += 1
    return result

