def triples_sum_to_zero(numbers):
    numbers = sorted(numbers)
    n = len(numbers)
    for i in range(n):
        # To avoid checking duplicates for the first element
        if i > 0 and numbers[i] == numbers[i-1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            s = numbers[i] + numbers[left] + numbers[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False

