def will_it_fly(q, w):
    def is_palindrome(seq):
        return list(seq) == list(reversed(seq))

    # Extract attributes from q
    # q could be an object with attributes or a dict with keys or a sequence
    okay = False
    can_fly = False
    weight = None

    # Try attribute access
    try:
        okay = getattr(q, "okay")
    except Exception:
        try:
            okay = q["okay"]
        except Exception:
            # If q is a sequence, treat okay as per palindrome condition
            if (isinstance(q, (list, tuple)) and 
                all(isinstance(x, (int, float)) for x in q)):
                okay = is_palindrome(q)
            else:
                # If we cannot determine okay, default False
                okay = False

    # can_fly
    try:
        can_fly = getattr(q, "can_fly")
    except Exception:
        try:
            can_fly = q["can_fly"]
        except Exception:
            can_fly = False

    # weight
    try:
        weight = getattr(q, "weight")
    except Exception:
        try:
            weight = q["weight"]
        except Exception:
            # If q is a sequence of numerics and okay is determined by palindrome,
            # sum weight as sum of elements
            if (isinstance(q, (list, tuple)) and
                all(isinstance(x, (int, float)) for x in q)):
                weight = sum(q)
            else:
                weight = None

    # Check conditions
    if not (okay and can_fly):
        return False

    if not (isinstance(weight, (int, float))):
        return False

    return weight <= w

