def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Since all items are distinct, at most one place where arr[i] > arr[i+1]
    # is allowed for a rotation to be sorted non-decreasingly.
    count_drop = 0
    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            count_drop += 1
            if count_drop > 1:
                return False
    return True

