def order_by_points(nums):
    def key_func(n):
        s = str(abs(n))
        digits = list(map(int, s))
        if n >= 0:
            return sum(digits)
        else:
            if digits:
                return -digits[0] + sum(digits[1:])
            else:
                return 0
    return sorted(nums, key=key_func)

