def monotonic(l: list):
    """Return True if list elements are monotonic (nondecreasing or nonincreasing), False otherwise.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([10, 10, 10])
    True
    >>> monotonic([])
    True
    >>> monotonic([1])
    True
