def sum_squares(lst):
    """
    This function takes a list of integers. For each entry:
    - If the index is a multiple of 3, square the value.
    - Else if the index is a multiple of 4 (and not a multiple of 3), cube the value.
    - Otherwise, leave the value unchanged.
    The function returns the sum of all the resulting values.
    """
    return sum(
        x**2 if i % 3 == 0 else (x**3 if i % 4 == 0 else x)
        for i, x in enumerate(lst)
    )

