def next_smallest_palindrome(num: int) -> int:
    # Find the smallest palindrome strictly greater than num

    if num < 0:
        # For negative input, the next palindrome greater is 0 if num < 0
        # but since negative number palindrome next larger is 0 or 1,
        # simplest is to start from max(num+1,0)
        start = max(num+1, 0)
    else:
        start = num + 1

    while True:
        s = str(start)
        if s == s[::-1]:
            return start
        start += 1

