def find_solution(a: int, b: int, n: int):
    # Try x from 0 upwards to find non-negative integer solution
    if b == 0:
        # Then equation is ax = n
        if a != 0 and n % a == 0 and n // a >= 0:
            return ('x = ', n // a, ', y = ', 0)
        else:
            return 'No solution'
    if a == 0:
        # Then equation is by = n
        if b != 0 and n % b == 0 and n // b >= 0:
            return ('x = ', 0, ', y = ', n // b)
        else:
            return 'No solution'

    x = 0
    # We can limit x to n // a + 1 if a > 0 else search until some reasonable limit
    # but since no domain restriction, just try until some upper bound or until no solution found
    # We can't do infinite loop, so we try up to a reasonable large number (e.g., max search space)
    # but no constraint given, so try up to some limit based on n and a,b sign
    # Let's consider the range from 0 to max_x where max_x = n//a if a>0 else 0 to some large number
    # Just try from 0 to 10**6 to avoid infinite loops
    limit = 10**6
    for x in range(limit + 1):
        rest = n - a * x
        if b != 0 and rest % b == 0:
            y = rest // b
            if y >= 0:
                return ('x = ', x, ', y = ', y)
    return 'No solution'

