def get_total_number_of_sequences(m: int, n: int) -> int:
    if n <= 0 or m < 1:
        return 0
    if n == 1:
        return m
    # dp[i][x] = number of sequences of length i ending with element x
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1
    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # prefix sums to optimize the inner loop
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp[x]
        for x in range(1, m + 1):
            # next element y must be >= 2 * x
            start = 2 * x
            if start <= m:
                new_dp[x] = prefix[m] - prefix[start - 1]
            else:
                new_dp[x] = 0
        dp = new_dp
    return sum(dp[1:]) if n > 1 else m

