def permute_string(s: str) -> None:
    def backtrack(path, counter):
        if len(path) == len(s):
            print(''.join(path))
            return
        for char in counter:
            if counter[char] > 0:
                counter[char] -= 1
                path.append(char)
                backtrack(path, counter)
                path.pop()
                counter[char] += 1

