from typing import List, Optional

def find_Max(arr: List[int], start: int, end: int) -> Optional[int]:
    if not arr or start > end or start < 0 or end >= len(arr):
        return None
    # If the array is not rotated or has only one element in the given range
    if arr[start] < arr[end]:
        return arr[end]
    if start == end:
        return arr[start]

    # Binary search for the index of the minimum element
    left, right = start, end
    while left < right:
        mid = (left + right) // 2
        if arr[mid] > arr[right]:
