def filter_data(data, min_height=None, max_height=None, min_width=None, max_width=None):
    """
    Filters students by height and width.

    Parameters:
    - data: dict mapping student names to (height, width) tuples.
    - min_height, max_height: optional numeric boundaries (inclusive) for height.
    - min_width, max_width: optional numeric boundaries (inclusive) for width.

    Returns:
