def check_Even_Parity(n: int) -> bool:
    # Count the number of 1 bits in the binary representation of n
    count_ones = 0
    x = n
    while x:
        count_ones += x & 1
        x >>= 1
    # Return True if the count of 1s is even, False otherwise
    return (count_ones % 2) == 0

