def substract_elements(t1, t2):
    if isinstance(t1, tuple) and isinstance(t2, tuple):
        # Both are tuples: subtract element-wise recursively
        length = min(len(t1), len(t2))
        result = tuple(substract_elements(t1[i], t2[i]) for i in range(length))
        if len(t1) > length:
            result += t1[length:]
        if len(t2) > length:
            # subtracting extra elements from nothing means subtracting these elements
            # we negate them as if from zero
            result += tuple(-x if not isinstance(x, tuple) else substract_elements((), x) for x in t2[length:])
        return result
    else:
        # At least one is not a tuple: treat as integers and subtract
        return (t1 if not isinstance(t1, tuple) else 0) - (t2 if not isinstance(t2, tuple) else 0)

