def lucky_num(n: int) -> list[int]:
    numbers = list(range(1, 10**6))  # start with a large range to ensure enough lucky numbers
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        del numbers[step-1::step]
        idx += 1
        if len(numbers) <= n:
            break
    return numbers[:n]

