def find_solution(a: int, b: int, n: int) -> Optional[Tuple[str, int, str, int]]:
    if b == 0:
        # If b = 0, ax = n => x = n/a if integer and non-negative
        if a != 0 and n % a == 0 and n // a >= 0:
            return ('x = ', n // a, ', y = ', 0)
        else:
            return None
    limit = 2 * abs(n)
    for x in range(limit + 1):
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            return ('x = ', x, ', y = ', y)
    return None

