def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return m

    # dp[i][x]: number of sequences of length i ending with x
    dp = [ [0]*(m+1) for _ in range(n+1) ]

    # For length 1, any element 1..m is valid
    for x in range(1, m+1):
        dp[1][x] = 1

    for length in range(2, n+1):
        for x in range(1, m+1):
            # The previous element y must satisfy y <= x/2
            # So we sum dp[length-1][y] for y in [1..x//2]
            limit = x // 2
            dp[length][x] = sum(dp[length-1][y] for y in range(1, limit+1))

    return sum(dp[n][x] for x in range(1, m+1))

