def find_Max(arr, low, high):
    if low > high:
        return None
    if low == high:
        return arr[low]

    # If subarray is already sorted, the last element is the largest
    if arr[low] < arr[high]:
        return arr[high]

    mid = (low + high) // 2

    # Check if mid is the largest element (greater than next element)
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]

    # Check if mid-1 is the largest element (greater than mid element)
    if mid > low and arr[mid - 1] > arr[mid]:
        return arr[mid - 1]

    # Decide which half to continue searching
    if arr[mid] > arr[low]:
        # Largest in right half
        return find_Max(arr, mid + 1, high)
    else:
        # Largest in left half
        return find_Max(arr, low, mid - 1)

