def lucky_num(n):
    if n <= 0:
        return []
    # Start with list of odd numbers since even numbers are removed in first step,
    # but include 1 as per user clarification.
    numbers = list(range(1, 2 * n * 10, 2))
    idx = 1  # start from second element (index 1), as per sieve definition
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th element starting from the step-th (1-based indexing)
        # Because the indexing here is 0-based, remove elements at indices which are
        # multiples of step, starting from step-1 index (0-based)
        del numbers[step-1::step]
        idx += 1
        if len(numbers) >= n:
            # We have enough lucky numbers
            break
    return numbers[:n]

