def compute_Last_Digit(a: int, b: int) -> int:
    if a == b:
        return 1
    if a > b:
        # a > b case: last digit of a! / b! = product from b+1 to a
        start, end = b + 1, a
    else:
        # a < b case: if difference >= 5 return 0, else product from a+1 to b
        if b - a >= 5:
            return 0
        start, end = a + 1, b

