def zip_tuples(t1: tuple, t2: tuple) -> tuple:
    if len(t1) == 0 or len(t2) == 0:
        return ()
    if len(t1) >= len(t2):
        longer, shorter = t1, t2
    else:
        longer, shorter = t2, t1
    result = tuple((longer[i], shorter[i % len(shorter)]) for i in range(len(longer)))
    if len(t1) >= len(t2):
        return result
    else:
        # If t2 is longer, reorder pairs so that elements correspond to (t1 element, t2 element)
        return tuple((pair[1], pair[0]) for pair in result)

