def next_smallest_palindrome(n: int) -> int:
    s = str(n + 1)
    length = len(s)

    # Helper to check if a string is a palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # For single digit numbers, next palindrome is always the next number
    if length == 1:
        return n + 1

    # Construct palindrome by mirroring the left half to the right
    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    odd_length = (length % 2 != 0)
    half_len = (length + 1) // 2
    left = s[:half_len]

    palindrome = make_palindrome(left, odd_length)

    if palindrome > s:
        return int(palindrome)
    else:
        # Increment the left half and construct palindrome again
        incremented = str(int(left) + 1)
        # Handle the case when incrementing the half increases its length
        if len(incremented) > len(left):
            # This happens when original number is like 999..9, so next palindrome is 100..001
            return int('1' + ('0' * (length - 1)) + '1')
        else:
            palindrome = make_palindrome(incremented, odd_length)
            return int(palindrome)

