def next_power_of_2(n: int) -> int:
    if n <= 1:
        return 1
    # Check if n is already a power of two
    if (n & (n - 1)) == 0:
        return n
    # Otherwise find the smallest power of two strictly greater than n
    power = 1
    while power <= n:
        power <<= 1
    return power

