def get_total_number_of_sequences(m: int, n: int) -> int:
    # Count sequences of length n using values 1..m where each next element is either double or half of the current, if integer and in 1..m.
    if n == 0:
        return 0
    if n == 1:
        return m

    # dp[i][x] = number of sequences of length i ending with x
    dp = [ [0]*(m+1) for _ in range(n+1) ]
    for x in range(1, m+1):
        dp[1][x] = 1

    for length in range(2, n+1):
        for x in range(1, m+1):
            # from previous element y to current x
            # possible if y*2 == x or y == 2*x
            # so y = x/2 if x even, or y = 2*x (if <= m)
            ways = 0
            if x % 2 == 0:
                ways += dp[length-1][x//2]
            if 2*x <= m:
                ways += dp[length-1][2*x]
            dp[length][x] = ways

    return sum(dp[n][1:])

