def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 0
    for v in d.values():
        if isinstance(v, dict):
            max_depth = max(max_depth, dict_depth(v))
        elif isinstance(v, (list, tuple)):
            for item in v:
                if isinstance(item, dict):
                    max_depth = max(max_depth, dict_depth(item))
    return 1 + max_depth

