    # Calculate cost to make string start with '0'
    cost_start_0 = 0
    # Calculate cost to make string start with '1'
    cost_start_1 = 0

    for i, ch in enumerate(s):
        expected_0 = '0' if i % 2 == 0 else '1'
        expected_1 = '1' if i % 2 == 0 else '0'
        if ch != expected_0:
