import random

def permute_string(s):
    # Generate all permutations including duplicates (simple recursion)
    def permute(prefix, remainder, result):
        if not remainder:
            result.append(prefix)
            return
        for i in range(len(remainder)):
            permute(prefix + remainder[i], remainder[:i] + remainder[i+1:], result)

