def find_Max(arr):
    if not arr:
        return None
    low, high = 0, len(arr) - 1
    # If the array is not rotated (sorted ascending)
    if arr[low] < arr[high]:
        return arr[high]
    while low <= high:
        mid = (low + high) // 2
        # check if mid is the max (greater than next element)
        if mid < len(arr) - 1 and arr[mid] > arr[mid + 1]:
            return arr[mid]
        # check if mid-1 is the max (greater than mid)
        if mid > 0 and arr[mid - 1] > arr[mid]:
            return arr[mid - 1]
        # decide which half to choose
        if arr[mid] >= arr[low]:
            low = mid + 1
        else:
            high = mid - 1
    # If no rotation point found, maximum is last element
    return arr[-1]

