def lucky_num(n):
    if n <= 0:
        return []
    # Start with odd numbers including 1: 1,3,5,7,...
    numbers = list(range(1, 2*n*10, 2))
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th element by position (1-based)
        # Keep elements where (position % step) != 0
        numbers = [num for i, num in enumerate(numbers, start=1) if i % step != 0]
        idx += 1
        if len(numbers) >= n:
            continue
        else:
            # If too few numbers, extend the list by more odd numbers
            last = numbers[-1]
            extend_to = last + 2 * n * 10
            extended = list(range(last + 2, extend_to, 2))
            numbers.extend(extended)
    return numbers[:n]

