def Find_Min_Length(lst):
    if not lst:
        return 0
    # Flatten the list of sublists into a single list of elements
    elements = []
    for sublist in lst:
        elements.extend(sublist)
    # Find the set of distinct elements in the entire flattened list
    distinct = set(elements)
    total_unique = len(distinct)
    if total_unique == 0:
        return 0

    # Use sliding window to find shortest sublist of lst (contiguous sublists)
    # that contains all distinct elements at least once when concatenated
    from collections import Counter

    # We will track counts of elements in the window by flattening sublists in the window
    # but avoid flattening every time by counting elements per sublist once
    sublist_counts = []
    for sublist in lst:
        c = Counter(sublist)
        sublist_counts.append(c)

    current_count = Counter()
    have = 0
    need = total_unique
    min_length = float('inf')
    left = 0

    for right in range(len(lst)):
        # Add sublist_counts[right] to current_count
        for k, v in sublist_counts[right].items():
            prev_count = current_count[k]
            current_count[k] += v
            # If previously count was zero and now positive, increment have
            if prev_count == 0 and current_count[k] > 0:
                have += 1

        # Try to shrink window from left while we still have all needed elements
        while have == need and left <= right:
            current_window_length = right - left + 1
            if current_window_length < min_length:
                min_length = current_window_length

            # Remove sublist_counts[left] from current_count
            for k, v in sublist_counts[left].items():
                current_count[k] -= v
                # If count falls to zero, decrement have
                if current_count[k] == 0:
                    have -= 1
            left += 1

    return 0 if min_length == float('inf') else min_length

