def find_solution(a: int, b: int, n: int):
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return 'No solution'
    x = 0
    while True:
        lhs = a * x
        diff = n - lhs
        if b != 0:
            if diff % b == 0:
                y = diff // b
                if y >= 0:
                    return (x, y)
        else:
            if diff == 0:
                return (x, 0)
        x += 1
        # To avoid infinite loop when no solution is possible:
        # If a > 0 and b > 0, n must be >= 0, else no solution.
        # We can bound x when a and b > 0, x > n//a + 1 no solution.
        # For other cases, we try until x > n if n >= 0 else 0.
        # Implement a reasonable upper bound to stop search when no solution:
        # The problem doesn't specify constraints, so use a heuristic:
        if (a > 0 and b > 0 and x > n // a + 1):
            break
        if n >= 0 and x > n:
            break
        if n < 0 and x > abs(n):
            break
    return 'No solution'

