def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 1:
        return m if m >= 1 else 0
    if n <= 0 or m <= 0:
        return 0

    # dp[i][x] = number of sequences of length i starting with element x
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for x in range(1, m + 1):
        dp[1][x] = 1

    for length in range(2, n + 1):
        # For each possible starting element x in sequence of length 'length'
        for x in range(1, m + 1):
            # sum all dp[length-1][y] where y is between 2*x and m inclusive
            # because next element must be >= 2*x and <= m
            start = 2 * x
            if start <= m:
                dp[length][x] = sum(dp[length - 1][start:m + 1])
            else:
                dp[length][x] = 0

    return sum(dp[n][1:m + 1])

