def find_Max(arr):
    if not arr:
        return None
    n = len(arr)
    low, high = 0, n - 1

    # If array is not rotated (first element <= last element), max is last element
    if arr[low] <= arr[high]:
        return arr[high]

    # Binary search for the index of minimum element
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            low = mid + 1
        else:
            high = mid

    # low is index of minimum element, max is element before it
    return arr[low - 1]

