def sum_Of_product(n: int) -> int:
    if n == 0:
        return 0
    # Calculate C(2n, n-1)
    # Use an efficient approach to compute binomial coefficient without overflow
    # C(a, b) = a! / (b! * (a-b)!)
    # We'll compute using a multiplicative formula to avoid large intermediate factorials

    a = 2 * n
    b = n - 1
    if b > a - b:
        b = a - b

    result = 1
    for i in range(1, b + 1):
        result = result * (a - b + i) // i

    return result

