def lucky_num(n):
    if n <= 0:
        return []
    numbers = list(range(1, 2 * n * n))  # generous upper bound to ensure enough lucky numbers
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n:
            continue
        # If numbers got too short, expand range and restart process
        # This is a fallback for very small initial range, but unlikely needed given the starting range
    return numbers[:n]

