def dif_Square(n: int) -> bool:
    # A number n can be expressed as difference of squares a^2 - b^2
    # = (a-b)(a+b). Let x = a-b, y = a+b. Then n = xy with y > x and
    # x and y have the same parity.
    # So n can be expressed as difference of squares iff it can be factored into two factors of the same parity.
    # Check all factor pairs of n for same parity.
    # Since factors can be negative, consider absolute value of n.
    abs_n = abs(n)
    # 0 can be represented as 0^2 - 0^2
    if n == 0:
        return True
    # Iterate over possible factors of abs_n
    # We check for factors x,y where xy = n and x,y have same parity.
    # x and y are integers, positive or negative; but checking positive factors suffices because negative factor pairs just swap signs.
    i = 1
    while i * i <= abs_n:
        if abs_n % i == 0:
            j = abs_n // i
            # Check if i and j have same parity
            if (i % 2) == (j % 2):
                # Check if product matches n or -n to allow negative factor pairs
                # For n positive, factors i,j product is n (positive)
                # For n negative, product is -n (positive), so actual factors could be -i * j = n or i * (-j) = n
                # But since we only check positive i,j, if n negative, factor pairs with opposite signs can represent n.
                # So if n and the product i*j differ in sign, it's still possible.
                # So the parity condition suffices.
                return True
        i += 1
    return False

