def remove_column(data, column):
    if isinstance(data, dict):
        # Remove key column from dict and recurse on values
        return {k: remove_column(v, column) for k, v in data.items() if k != column}
    elif isinstance(data, list):
        # If list of lists, remove element at index column from each inner list
        if all(isinstance(elem, list) for elem in data):
            return [elem[:column] + elem[column + 1:] if 0 <= column < len(elem) else elem for elem in data]
        else:
            # Otherwise recurse on each element
            return [remove_column(elem, column) for elem in data]
    else:
        # Leave other data unchanged
        return data

