def smallest_missing(array, start, end):
    # If the segment is empty, the smallest missing is start
    if start > end:
        return start
    mid = (start + end) // 2
    # If the element at mid matches the index mid, missing is in right half
    if array[mid] == mid:
        return smallest_missing(array, mid + 1, end)
    else:
        # Otherwise, missing is in left half
        return smallest_missing(array, start, mid - 1)

