def lucky_num(n):
    if n <= 0:
        return []
    numbers = list(range(1, 2 * n * n))  # a sufficiently large initial list
    idx = 1  # index of the current step's k in numbers
    while len(numbers) > n:
        k = numbers[idx]
        if k > len(numbers):
            break
        # Remove every k-th number from the current list, 1-based indexing
        del numbers[k-1::k]
        idx += 1
    return numbers[:n]

