def compute_Last_Digit(a: int, b: int) -> int:
    if a > b:
        return 0
    # factorial(b) // factorial(a) = product of integers from a+1 to b
    # Check divisibility: factorial(a) divides factorial(b) always if a <= b,
    # so no need to check divisibility again.
    # But user wants to return 0 if not divisible, so it is always divisible if a <= b.
    # Compute product of numbers from a+1 to b and return last digit.
    product = 1
    for i in range(a + 1, b + 1):
        product *= i
        product %= 10  # Keep only last digit to avoid overflow.
    return product

