def zip_tuples(*iterables):
    if not iterables:
        return []
    first_len = len(iterables[0])
    # For each iterable, cycle it if shorter than first_len, otherwise truncate
    cycled_iterables = []
    for it in iterables:
        length = len(it)
        if length < first_len and length > 0:
            # cycle the iterable to match first_len
            extended = []
            idx = 0
            while len(extended) < first_len:
                extended.append(it[idx % length])
                idx += 1
            cycled_iterables.append(extended)
        else:
            cycled_iterables.append(it[:first_len])
    # Now zip the iterables element-wise into tuples
    return [tuple(elements) for elements in zip(*cycled_iterables)]

