def find_solution(a: int, b: int, n: int):
    x = 0
    while True:
        left = n - a * x
        if b == 0:
            if left == 0:
                return ('x = ', x, ', y = ', 0)
            else:
                return 'No solution'
        if left % b == 0:
            y = left // b
            if y >= 0:
                return ('x = ', x, ', y = ', y)
        x += 1
        if x > 1000:
            break
    return 'No solution'

