def get_total_number_of_sequences(N: int, K: int, start_value: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(current_value: int, length_left: int) -> int:
        if length_left == 1:
            # Only one element left, sequence of length 1 is valid if current_value in range
            return 1 if 1 <= current_value <= N else 0
        if current_value > N:
            return 0
        total = 0
        next_value = current_value * 2
        # next_value must be between 1 and N
        if next_value <= N:
            total += count_sequences(next_value, length_left - 1)
        else:
            # No valid next value, so no sequences
            total += 0
        return total

    if not (1 <= start_value <= N):
        return 0
    return count_sequences(start_value, K)

