def remove_column(data, index):
    def remove_from_collection(coll, idx):
        # Remove element at idx from coll, preserving type
        if not isinstance(coll, (list, tuple)):
            return coll
        length = len(coll)
        # Adjust negative index
        if idx < 0:
            idx += length
        # If index out of range, return coll unchanged
        if idx < 0 or idx >= length:
            return coll
        if isinstance(coll, list):
            return coll[:idx] + coll[idx+1:]
        else:  # tuple
            return coll[:idx] + coll[idx+1:]

    # Check if data is a collection of collections
    if isinstance(data, (list, tuple)):
        # Check if all elements are list or tuple
        if all(isinstance(inner, (list, tuple)) for inner in data):
            # Remove element at index from each inner collection preserving types
            result = [remove_from_collection(inner, index) for inner in data]
            # Preserve outer type
            if isinstance(data, list):
                return result
            else:
                return tuple(result)
        else:
            # data is a single collection, remove element at index from it
            return remove_from_collection(data, index)
    else:
        # data is not a collection of collections, return data unchanged
        return data

