def move_num(texts, numbers):
    """
    Insert numeric values into a group of text strings.

    Args:
        texts: list of str
        numbers: list of int or float

    Returns:
        list of str: each element is a text string possibly appended by a number separated by a space;
                     if texts and numbers differ in length, leftover elements are appended as is.
    """
    result = []
    min_len = min(len(texts), len(numbers))
    for i in range(min_len):
        result.append(texts[i] + ' ' + str(numbers[i]))
    if len(texts) > len(numbers):
        result.extend(texts[min_len:])
    elif len(numbers) > len(texts):
        # leftover numbers have no text to append to, so convert to str as separate elements
        result.extend(str(n) for n in numbers[min_len:])
    return result

