def check_subset(group1, group2):
    # For each unique item in group1, check if its count in group1 is less than or equal to its count in group2
    # This ensures that group1 is a subset of group2 considering item multiplicity.
    group1_list = list(group1)
    group2_list = list(group2)
    unique_items = []
    for item in group1_list:
        if item not in unique_items:
            unique_items.append(item)
    for item in unique_items:
        if group1_list.count(item) > group2_list.count(item):
            return False
    return True

