def capital_words_spaces(text: str) -> str:
    result = []
    length = len(text)
    for i, c in enumerate(text):
        if i > 0:
            prev = text[i - 1]
            next_char = text[i + 1] if i + 1 < length else ''
            # Insert space if current is uppercase, previous is a word char (not space),
            # and next is lowercase
            if (
                c.isupper()
                and prev.isalnum()
                and next_char.islower()
            ):
                result.append(' ')
        result.append(c)
    return ''.join(result)

