def lucky_num(n):
    if n <= 0:
        return []
    # Initialize the list with natural numbers starting from 1
    numbers = list(range(1, 2 * n * 10))  # overshoot to ensure enough lucky numbers
    idx = 1  # start from the second element index (step)
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list (1-based)
        numbers = [num for i, num in enumerate(numbers, start=1) if i % step != 0]
        idx += 1
        if len(numbers) >= n:
            continue
        else:
            break
    return numbers[:n]

