def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 0:
        return 0
    # dp[i][x] = number of sequences of length i ending with x
    dp = [ [0] * (m+1) for _ in range(n+1) ]
    # base case: sequences of length 1
    for x in range(1, m+1):
        dp[1][x] = 1
    for i in range(2, n+1):
        for x in range(1, m+1):
            # previous element y must satisfy y <= x//2
            # sum over y from 1 to x//2 of dp[i-1][y]
            max_prev = x // 2
            if max_prev >= 1:
                dp[i][x] = sum(dp[i-1][y] for y in range(1, max_prev+1))
    return sum(dp[n][x] for x in range(1, m+1))

