def find_Max(arr: list[int]) -> int | None:
    if not arr:
        return None
    low, high = 0, len(arr) - 1
    # If array is not rotated (sorted ascending), max is last element
    if arr[low] < arr[high]:
        return arr[high]
    # Binary search for the pivot (smallest element)
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            low = mid + 1
        else:
            high = mid
    # low is index of smallest element, so max is element before it (wrap around)
    return arr[low - 1]

