def lucky_num(n):
    if n <= 0:
        return []
    seq = list(range(1, 10 * n))  # start with enough numbers
    lucky_numbers = []
    idx = 0
    while len(lucky_numbers) < n:
        if idx >= len(seq):
            break
        lucky = seq[idx]
        lucky_numbers.append(lucky)
        # Remove every lucky-th element from seq, starting at index lucky-1
        seq = [seq[i] for i in range(len(seq)) if (i + 1) % lucky != 0]
        idx = 0
    return lucky_numbers

